-- Gift Chest has one authoritative notification path:
-- the per-timer server job calls the notify Edge Function, which inserts
-- the inbox row and sends FCM. The legacy minute cron inserted a second
-- "Pro Earn" inbox row for the same unlock.

do $$
declare
  r record;
begin
  for r in
    select jobid
    from cron.job
    where jobname = 'gift-chest-ready-notifications'
  loop
    perform cron.unschedule(r.jobid);
  end loop;
end;
$$;

-- Remove only legacy duplicate chest-ready rows generated by the old cron.
delete from public.notifications
where type = 'chest_ready'
  and lower(coalesce("senderName", '')) = 'pro earn';

-- Client timer sync must not set isUnlocked. Doing so fires the timer-scheduling
-- trigger and cancels the server job before it can deliver the push notification.
-- The server-side scheduled job is the authority that marks the chest unlocked.
create or replace function public.sync_chest_timer(p_remaining_seconds integer)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_unlock timestamptz;
  v_remaining integer;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select "unlockAt"
    into v_unlock
  from public.chest_progress
  where uid = v_uid
  for update;

  if not found or v_unlock is null then
    return;
  end if;

  v_remaining := greatest(
    0,
    ceil(extract(epoch from (v_unlock - now())))::integer
  );

  update public.chest_progress
  set "remainingSeconds" = v_remaining,
      "updatedAt" = now()
  where uid = v_uid;
end;
$$;

revoke all on function public.sync_chest_timer(integer) from public, anon;
grant execute on function public.sync_chest_timer(integer) to authenticated, service_role;
